"""Reviewed transcript comment changes; source bodies and operation structure stay in place."""
from pathlib import Path
import json,re
ROOT=Path(__file__).resolve().parents[3];CHANGES=[]
def edit(name,old,new,finding):
 p=ROOT/'dev_docs/agents/transcripts'/name
 s=p.read_text()
 # Whole comment paragraphs have one common indentation inside their Kotlin body.
 match=re.search(r'(?m)^([ \t]*)'+re.escape(old.splitlines()[0]),s)
 if match:
  pad=match[1];old=old.replace('\n','\n'+pad);new=new.replace('\n','\n'+pad)
 assert old in s,(name,old)
 s=s.replace(old,new);p.write_text(s);CHANGES.append({'path':str(p.relative_to(ROOT)),'finding':finding,'old':old,'new':new})
edit('arclength_spacing_demo.yaml',"// The mechanism, live. `flatness` is the OLD subdivision criterion: the distance of the\n// control points from the chord. `skew` is the term added on 2026-07-31: the distance\n// between the curve's mid-PARAMETER point B(0.5) and the chord's mid-POINT. Neither\n// subsumes the other, which is why the criterion takes the larger of the two.","// Flatness measures control-point distance from the chord; skew measures the distance\n// between B(0.5) and the chord midpoint. Use the larger: either test can miss a curve\n// that the other detects.",'032cda1ce14b-01')
